ws=wb['Task']
errors=[]
if wb.sheetnames != ['Task', 'Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')
def is_formula(v):
    return isinstance(v,str) and v.startswith('=')
# Lookup formulas
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        v=ws.cell(r,c).value
