            errors.append(f'{ws.cell(r,c).coordinate} lookup formula suspicious: {v}')
# Gap formulas
for r in range(35,41):
    for c in range(8,13):
        v=ws.cell(r,c).value
        if not is_formula(v):
            errors.append(f'{ws.cell(r,c).coordinate} not gap formula: {v!r}')
# Stats formulas and PERCENTILE.INC
